 private static VotingRuleDto RuleDto(VotingRule r)=>new(r.Id,r.Code,r.Description,r.Version,r.PreviousVersionId,r.Status,r.EffectiveFrom,r.EffectiveTo,Read<VotingCriteria>(r.CriteriaJson),r.ReviewNote,r.ReviewedBy,r.ReviewedAt);
 public async Task<IReadOnlyList<VotingRuleDto>> Rules(Guid condo,CancellationToken ct){await Condo(condo,ct);return(await db.VotingRules.Where(r=>r.CondominiumId==condo).OrderBy(r=>r.Code).ThenByDescending(r=>r.Version).ToListAsync(ct)).Select(RuleDto).ToArray();}
 private async Task<T> RuleWrite<T>(Guid condo,Func<Task<T>> action,CancellationToken ct){current.RequireAdmin();await using var tx=await db.Database.BeginTransactionAsync(ct);await Condo(condo,ct);await db.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM \"Condominiums\" WHERE \"Id\"={condo} AND \"TenantId\"={Tenant} FOR UPDATE",ct);if(!await db.Condominiums.AnyAsync(c=>c.Id==condo&&c.IsActive,ct))throw new InvalidOperationException("Condominio inattivo.");var result=await action();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return result;}
 public Task<VotingRuleDto> SaveRule(Guid condo,VotingRuleInput i,CancellationToken ct)=>RuleWrite(condo,async()=>{ArgumentNullException.ThrowIfNull(i.Criteria);i.Criteria.Validate();var code=Guard.Text(i.Code).ToUpperInvariant();var last=await db.VotingRules.Where(r=>r.CondominiumId==condo&&r.Code==code).OrderByDescending(r=>r.Version).FirstOrDefaultAsync(ct);if(last?.Id!=i.PreviousVersionId)throw new InvalidOperationException("Indicare l'ultima versione del criterio; usare un nuovo codice per un criterio distinto.");var r=new VotingRule(Tenant,condo,code,i.Description,(last?.Version??0)+1,i.PreviousVersionId,Json(i.Criteria),i.EffectiveFrom,i.EffectiveTo,Actor);db.Add(r);db.SecurityAudits.Add(new(){Id=Guid.NewGuid(),TenantId=Tenant,ActorUserId=Actor,SubjectId=r.Id,Event="Voting.RuleCreated",Timestamp=DateTimeOffset.UtcNow});return RuleDto(r);},ct);
 public Task<VotingRuleDto> ReviewRule(Guid condo,Guid id,RuleReviewInput? i,CancellationToken ct)=>RuleWrite(condo,async()=>{var r=await db.VotingRules.SingleOrDefaultAsync(r=>r.CondominiumId==condo&&r.Id==id,ct)??throw new NotFoundException();if(i==null)r.Retire();else r.Activate(Actor,i.ReviewNote);db.SecurityAudits.Add(new(){Id=Guid.NewGuid(),TenantId=Tenant,ActorUserId=Actor,SubjectId=r.Id,Event="Voting.RuleReviewed",Timestamp=DateTimeOffset.UtcNow});return RuleDto(r);},ct);
 private async Task<DecisionsDto> DecisionMutation(Guid condo,Guid meeting,int version,string operation,Guid? request,object input,Func<CondominiumMeeting,Task> action,CancellationToken ct)
 {
  if(operation is "ResolutionFinalized" or "ResolutionApplied" or "Completed")current.RequireAdmin();
  // Version is a precondition, not part of the idempotent command's identity.
  var payload=System.Text.Json.Nodes.JsonNode.Parse(Json(input))!.AsObject();payload.Remove("ExpectedVersion");var hash=Hash(new{operation,Payload=payload});
  async Task<bool> Replay(){if(request==null)return false;Guard.Id(request.Value);var saved=await db.MeetingDecisionRequests.SingleOrDefaultAsync(r=>r.MeetingId==meeting&&r.RequestId==request,ct);if(saved==null)return false;if(saved.RequestHash!=hash||saved.Operation!=operation)throw new InvalidOperationException("Chiave riutilizzata con parametri diversi.");return true;}
  await Mutate(condo,meeting,version,operation,async row=>{await action(row);if(request!=null)db.Add(new MeetingDecisionRequest(Tenant,condo,meeting,request.Value,hash,operation));},ct,Replay);return await Decisions(condo,meeting,ct);
 }
 private async Task<VotingRule> ApplicableRule(Guid condo,Guid id,MeetingSession session,VotingPurpose purpose,AgendaCategory? category,DateTimeOffset at,CancellationToken ct){var r=await db.VotingRules.SingleOrDefaultAsync(r=>r.CondominiumId==condo&&r.Id==id,ct)??throw new NotFoundException();var c=Read<VotingCriteria>(r.CriteriaJson);var date=DateOnly.FromDateTime(at.UtcDateTime);if(r.Status!=VotingRuleStatus.Active||r.EffectiveFrom>date||(r.EffectiveTo!=null&&r.EffectiveTo<date)||c.Call!=session.Call||c.Purpose!=purpose||(c.Category!=null&&c.Category!=category))throw new InvalidOperationException("Criterio non attivo, fuori ambito o non applicabile alla sessione/materia.");return r;}
 private async Task<MeetingSession> VotingSession(Guid meeting,Guid id,CancellationToken ct)=>await db.MeetingSessions.SingleOrDefaultAsync(s=>s.MeetingId==meeting&&s.Id==id,ct)??throw new NotFoundException();
 private async Task<VotingElectorate> Electorate(CondominiumMeeting m,MeetingSession session,DateTimeOffset at,ElectorateOptions options,CancellationToken ct)
 {
  ArgumentNullException.ThrowIfNull(options);ArgumentNullException.ThrowIfNull(options.Exclusions);Guard.Text(options.Acknowledgement,2000);if(at==default||at>DateTimeOffset.UtcNow.AddSeconds(5))throw new ArgumentException("Istante di verifica non valido.");var snapshot=await db.MeetingSnapshots.SingleOrDefaultAsync(s=>s.Id==m.CurrentSnapshotId&&s.MeetingId==m.Id,ct)??throw new InvalidOperationException("Snapshot assembleare assente.");var p=Read<ParticipantsPreview>(snapshot.ContentJson);var errors=new List<string>();if(at<snapshot.CreatedAt)errors.Add("Istante precedente allo snapshot: ricostruzione non determinabile.");if(p.Denominator==null||p.Units.Any(u=>u.Millesimals==null)||p.Units.Sum(u=>u.Millesimals??0)!=p.Denominator)errors.Add("Quote/denominatore non completi o non coerenti.");
  if(options.Exclusions.Select(e=>e.PropertyUnitId).Distinct().Count()!=options.Exclusions.Count)throw new ArgumentException("Esclusioni duplicate.");foreach(var e in options.Exclusions){Guard.Text(e.Reason,2000);if(!p.Units.Any(u=>u.Id==e.PropertyUnitId))throw new NotFoundException();}
  var assignments=options.Assignments??[];if(assignments.Select(a=>a.PropertyUnitId).Distinct().Count()!=assignments.Count)throw new ArgumentException("Titolarità per materia duplicate.");foreach(var a in assignments){Guard.Text(a.Reason,2000);if(!p.Units.Any(u=>u.Id==a.PropertyUnitId&&u.Holdings.Any(h=>h.PersonId==a.PersonId)))throw new ArgumentException("Soggetto non titolare nello snapshot.");}
  if(options.AdministratorPersonId!=null&&!await db.People.AnyAsync(x=>x.Id==options.AdministratorPersonId,ct))throw new NotFoundException();
  var attendees=await db.MeetingAttendances.Where(a=>a.MeetingId==m.Id&&a.SessionId==session.Id&&a.CheckInAt<=at&&(a.CheckOutAt==null||a.CheckOutAt>at)).ToListAsync(ct);var aus=await db.MeetingAttendanceUnits.Where(a=>a.MeetingId==m.Id&&a.SessionId==session.Id).ToListAsync(ct);var proxies=await db.MeetingProxies.Where(x=>x.MeetingId==m.Id&&x.SnapshotId==snapshot.Id).ToListAsync(ct);var pus=await db.MeetingProxyUnits.Where(x=>x.MeetingId==m.Id).ToListAsync(ct);
  var units=p.Units.Where(u=>!options.Exclusions.Any(e=>e.PropertyUnitId==u.Id)).ToArray();var parts=new List<(ParticipantUnit Unit,Guid Principal,string Key,Guid? By)>();
  foreach(var u in units){var assignment=assignments.SingleOrDefault(a=>a.PropertyUnitId==u.Id);var principal=assignment?.PersonId??u.RepresentativeId;if(principal==null){errors.Add("Rappresentanza unitaria non definita: "+u.Code);continue;}foreach(var anomaly in u.Anomalies.Where(a=>!a.StartsWith("Titoli diversi")&&!a.StartsWith("Rappresentanza unitaria")))errors.Add(u.Code+": "+anomaly);if(u.Holdings.Any(h=>h.Role is UnitPersonRole.Usufructuary or UnitPersonRole.Other)&&assignment==null)errors.Add("Titolarità per materia da verificare esplicitamente: "+u.Code);
   var propertyTitle=u.Holdings.Any(h=>h.PersonId==principal&&h.Role is UnitPersonRole.Owner or UnitPersonRole.CoOwner);var holders=u.Holdings.Where(h=>propertyTitle?h.Role is UnitPersonRole.Owner or UnitPersonRole.CoOwner:h.PersonId==principal).Select(h=>h.PersonId).Distinct().Order().ToArray();if(holders.Length==0)holders=[principal.Value];var key=Hash(holders);var actors=new HashSet<Guid>();
   foreach(var attendance in attendees.Where(a=>a.Type!=AttendanceType.ByProxy&&a.PersonId==principal))actors.Add(attendance.PersonId);
   foreach(var proxy in proxies.Where(x=>x.DelegatorId==principal&&pus.Any(xu=>xu.ProxyId==x.Id&&xu.PropertyUnitId==u.Id))){var delegatePresent=attendees.Any(a=>(a.RepresentedById??a.PersonId)==proxy.DelegateId);if(!delegatePresent)continue;if(proxy.Status==Domain.ProxyStatus.Verified&&proxy.VerifiedAt<=at&&proxy.GrantedAt<=at&&pus.Any(x=>x.ProxyId==proxy.Id&&x.PropertyUnitId==u.Id&&x.IsActive)){if(proxy.DelegateId==options.AdministratorPersonId)errors.Add("Delega all'amministratore: "+u.Code);if(string.IsNullOrWhiteSpace(proxy.DocumentReference))errors.Add("Riferimento alla delega scritta mancante: "+u.Code);actors.Add(proxy.DelegateId);}else if(proxy.Status==Domain.ProxyStatus.Revoked&&at<proxy.UpdatedAt)errors.Add("Delega revocata: verifica storica non determinabile automaticamente.");}
   if(actors.Count>1)errors.Add("Doppia rappresentanza: "+u.Code);parts.Add((u,principal.Value,key,actors.Count==1?actors.Single():null));
  }
  // Intersecting ownership groups cannot be silently collapsed or counted twice.
  foreach(var person in units.SelectMany(u=>u.Holdings.Where(h=>h.Role is UnitPersonRole.Owner or UnitPersonRole.CoOwner).Select(h=>h.PersonId)).Distinct()){var keys=parts.Where(x=>x.Unit.Holdings.Any(h=>h.PersonId==person&&h.Role is UnitPersonRole.Owner or UnitPersonRole.CoOwner)&&(assignments.SingleOrDefault(a=>a.PropertyUnitId==x.Unit.Id)==null||assignments.Single(a=>a.PropertyUnitId==x.Unit.Id).PersonId==person)).Select(x=>x.Key).Distinct().ToArray();if(keys.Length>1)errors.Add("Gruppi di titolarità sovrapposti: determinazione delle teste da riconciliare esplicitamente.");}
  var rights=new List<ElectoralRight>();foreach(var group in parts.GroupBy(x=>x.Key).OrderBy(x=>x.Key)){var principals=group.Select(x=>x.Principal).Distinct().ToArray();var actors=group.Select(x=>x.By).Distinct().ToArray();if(principals.Length!=1||actors.Length!=1)errors.Add("Rappresentanza frammentata per uno stesso centro di voto.");var pr=principals[0];var by=actors.Length==1?actors[0]:null;string Name(Guid person)=>p.People.SingleOrDefault(x=>x.Id==person)?.Name??proxies.FirstOrDefault(x=>x.DelegateId==person)?.DelegateName??person.ToString();rights.Add(new(group.Key,pr,Name(pr),by,by==null?null:Name(by.Value),group.Select(x=>x.Unit.Id).Order().ToArray(),group.Sum(x=>x.Unit.Millesimals??0),by!=null));}
  var requiredPeople=units.SelectMany(u=>u.Holdings).Select(h=>h.PersonId).Distinct().ToArray();var notified=await db.MeetingNotices.Where(n=>n.MeetingId==m.Id&&n.SnapshotId==snapshot.Id&&(n.Status==Domain.NoticeStatus.Sent||n.Status==Domain.NoticeStatus.Delivered)&&n.SentAt<=at).Select(n=>n.PersonId).Distinct().ToArrayAsync(ct);if(requiredPeople.Except(notified).Any())errors.Add("Invio delle convocazioni non dichiarato per tutti i potenziali aventi diritto inclusi.");
  var core=new{snapshot.Id,At=at,Building=p.Denominator??0,Rights=rights,options.Exclusions,options.Assignments,options.Acknowledgement,options.AdministratorPersonId,Anomalies=errors};return new(snapshot.Id,at,p.Denominator??0,rights,options.Exclusions,errors.Distinct().ToArray(),options.Acknowledgement,Hash(core),options,Json(new{Attendances=attendees.Select(a=>new{a.Id,a.PersonId,a.Type,a.RepresentedById,a.ProxyId,a.CheckInAt,a.CheckOutAt}),Proxies=proxies.Select(p=>new{p.Id,p.DelegatorId,p.DelegateId,p.Status,p.VerifiedBy,p.VerifiedAt,p.GrantedAt,HasDocument=!string.IsNullOrWhiteSpace(p.DocumentReference)}),NotifiedPeople=notified}));
 }
 private async Task<TargetEvidence?> Target(Guid condo,MeetingAgendaItem agenda,CancellationToken ct)
 {
  if(agenda.RelatedId==null||agenda.RelatedType==null)return null;
  if(agenda.RelatedType==MeetingReference.Budget){var b=(await budgetService.List(condo,null,ct)).SingleOrDefault(b=>b.Id==agenda.RelatedId)??throw new NotFoundException();var content=Json(new{b.Id,b.Version,b.AccountingPeriodId,b.Description,b.Notes,b.Lines,b.Total});return new(MeetingReference.Budget,b.Id,b.Version,b.Status.ToString(),Hash(content),content);}
  if(agenda.RelatedType==MeetingReference.FinalStatement){var f=await db.FinalStatementRows.SingleOrDefaultAsync(f=>f.Id==agenda.RelatedId&&f.CondominiumId==condo,ct)??throw new NotFoundException();var content=Json(new{f.Id,f.Version,f.AccountingPeriodId,f.Description,f.Notes,f.SourceFingerprint,f.SnapshotJson});return new(MeetingReference.FinalStatement,f.Id,f.Version,f.Status.ToString(),Hash(content),content);}
  var period=await db.AccountingPeriods.SingleOrDefaultAsync(p=>p.Id==agenda.RelatedId&&p.CondominiumId==condo,ct)??throw new NotFoundException();var text=Json(new{period.Id,period.Code,period.Name,period.StartsOn,period.EndsOn});return new(MeetingReference.AccountingPeriod,period.Id,1,period.Status.ToString(),Hash(text),text);
 }
